"use strict";
// Writes SEED oracle entries (seed.oracle/0.1) for RAFT from RAFT's own committed engine golden vectors.
// The expected values come from the vectors (generated by RAFT's Python reference engine and reproduced by its
// TypeScript engine), never from running the adapter. Usage: node scripts/gen-raft-oracles.cjs <path to the RAFT repo>
// Output: <repo>/oracles/seed/{README.md, models/, entries/}. Re-running with unchanged vectors rewrites identical files.

const fs = require("node:fs");
const path = require("node:path");
const crypto = require("node:crypto");

const repo = process.argv[2];
if (!repo) {
  console.error("usage: node scripts/gen-raft-oracles.cjs <path to the RAFT repo>");
  process.exit(2);
}
const vectorsDir = path.join(repo, "schema", "engine-vectors");
const coreDir = path.join(repo, "schema", "vectors", "synthetic-core");
const out = path.join(repo, "oracles", "seed");
const NL = String.fromCharCode(10);

const sha = (d) => crypto.createHash("sha256").update(d).digest("hex");
function canonical(v) {
  if (v === null || typeof v !== "object") return JSON.stringify(v);
  if (Array.isArray(v)) return "[" + v.map(canonical).join(",") + "]";
  return "{" + Object.keys(v).sort().map((k) => JSON.stringify(k) + ":" + canonical(v[k])).join(",") + "}";
}
const write = (p, text) => {
  fs.mkdirSync(path.dirname(p), { recursive: true });
  fs.writeFileSync(p, text);
};
const pretty = (v) => JSON.stringify(v, null, 2) + NL;

function listFiles(dir, base = dir) {
  const files = [];
  for (const name of fs.readdirSync(dir).sort()) {
    const p = path.join(dir, name);
    if (fs.statSync(p).isDirectory()) files.push(...listFiles(p, base));
    else files.push(path.relative(base, p).split(path.sep).join("/"));
  }
  return files;
}

fs.rmSync(out, { recursive: true, force: true });
for (const rel of listFiles(coreDir)) write(path.join(out, "models", "lib", rel), fs.readFileSync(path.join(coreDir, rel)));
const libInputs = listFiles(path.join(out, "models", "lib")).map((rel) => ({ path: "models/lib/" + rel }));

const baseCase = (vec) => ({
  format: "raft-headless-case",
  version: 1,
  library: "lib",
  seed: vec.seed,
  init: vec.init,
  config: vec.config,
  steps: vec.steps,
  sampleEvery: vec.sampleEvery,
  script: vec.script.map((i) => ({ ...i, clientId: "local" })),
});

function inputsFor(casePath) {
  return [casePath, ...libInputs.map((i) => i.path)].map((p) => ({ path: p, sha256: sha(fs.readFileSync(path.join(out, p))) }));
}

function entry(o) {
  const e = {
    schema: "seed.oracle/0.1",
    oracleId: o.id,
    entryVersion: 1,
    adapter: "raft",
    adapterVersions: ["*"],
    tag: o.tag,
    inputs: inputsFor(o.casePath),
    expected: o.expected,
    ...(o.tolerance ? { tolerance: o.tolerance } : {}),
    source: o.source,
    coverage: o.coverage,
  };
  e.toleranceHash = sha(canonical({ expected: e.expected, tolerance: e.tolerance === undefined ? null : e.tolerance }));
  write(path.join(out, "entries", o.id + ".json"), pretty(e));
}

const QUANTITIES = [
  { name: "power", key: "power", unit: "W", tolerance: "power" },
  { name: "fuelTemp", key: "fuelTemp", unit: "K", tolerance: "temperature" },
  { name: "energy", key: "energy", unit: "J", tolerance: "power" },
];

let good = 0;
for (const file of fs.readdirSync(vectorsDir).filter((f) => f.endsWith(".json")).sort()) {
  const vec = JSON.parse(fs.readFileSync(path.join(vectorsDir, file), "utf8"));
  const casePath = "models/" + vec.name + ".case.json";
  write(path.join(out, casePath), pretty(baseCase(vec)));
  const last = vec.samples[vec.samples.length - 1];
  for (const q of QUANTITIES) {
    const tol = vec.tolerances[q.tolerance];
    entry({
      id: "raft-" + vec.name + "-final-" + q.name.toLowerCase(),
      tag: "good",
      casePath,
      expected: { quantity: q.name, value: last[q.key], unit: q.unit },
      tolerance: { abs: tol.abs, rel: tol.rel },
      source: {
        kind: "direct-engine",
        text: "RAFT engine golden vector " + vec.name + " (schema/engine-vectors/" + file + "), last sample at step " + last.step + "; the tolerance is the vector's own " + q.tolerance + " tolerance.",
        check: "Second implementation: the vectors are generated by the Python reference engine (physics_ref) and reproduced by the TypeScript engine (web/src/sim) within these tolerances in RAFT's own test suite.",
      },
      coverage: { quantities: [q.name], domain: "synthetic-core library, point kinetics with lumped thermal feedback, scenario " + vec.name },
    });
    good++;
  }
}

// Bad input: the case must be refused with a named code. Each is the scram case with one fault.
const scram = JSON.parse(fs.readFileSync(path.join(vectorsDir, "scram.json"), "utf8"));
const BAD = [
  { id: "raft-bad-outerdt-zero", edit: (c) => (c.config = { outerDt: 0 }), code: "E_SCHEMA_INVALID", what: "outerDt 0 (time would not advance)" },
  { id: "raft-bad-steps-zero", edit: (c) => (c.steps = 0), code: "E_SCHEMA_INVALID", what: "zero steps" },
  { id: "raft-bad-future-version", edit: (c) => (c.version = 2), code: "E_SCHEMA_VERSION", what: "a case version this runner does not read" },
  { id: "raft-bad-no-equilibrium", edit: (c) => (c.init = { rods: { safety: 1.0, regulating: 1.0, transient: 1.0 } }), code: "E_OUT_OF_DOMAIN", what: "all rods out, so no source-level equilibrium exists" },
];
for (const b of BAD) {
  const c = baseCase(scram);
  b.edit(c);
  const casePath = "models/" + b.id + ".case.json";
  write(path.join(out, casePath), pretty(c));
  entry({
    id: b.id,
    tag: "bad-input",
    casePath,
    expected: { refusalCode: b.code },
    source: { kind: "hand", text: "The case is the scram vector with one fault: " + b.what + ". The runner must refuse it before running; SEED reports " + b.code + ".", check: "RAFT's headless runner tests refuse the same faults (web/src/headless/run.test.ts)." },
    coverage: { quantities: ["case-validation"], domain: "headless case validation" },
  });
}

write(
  path.join(out, "README.md"),
  [
    "# SEED oracle entries for RAFT",
    "",
    "Generated by `scripts/gen-raft-oracles.cjs` in bluetyde/seed from this repo's engine golden vectors (`schema/engine-vectors/`).",
    "Entries in `entries/` are `seed.oracle/0.1` documents; `models/` holds the cases and the synthetic library they pin by hash.",
    "Expected values come from the committed vectors, not from any run of the adapter. A tolerance is part of the entry's hash:",
    "changing it needs a new `entryVersion` made by a human.",
    "",
    good + " good entries (final power, fuel temperature and energy of each of the six vectors) and " + BAD.length + " bad-input entries.",
    "Not covered: any library other than the synthetic core, burnup, xenon and iodine, reactivity feedback beyond the vectors.",
    "",
  ].join(NL)
);
console.log("wrote " + good + " good and " + BAD.length + " bad-input entries to " + out);
